 #[Route('/payments',methods:['POST'])]public function payment(Request $r,EntityManagerInterface $em,UserAccessService $access):JsonResponse{if($denied=$access->require(UserAccessService::ROLE_GERANT))return$denied;$d=$r->toArray();$invoice=$em->getRepository(SupplierInvoice::class)->find((int)($d['invoiceId']??0));$amount=max(0,(float)($d['amount']??0));if($invoice&&!$access->canAccessStation($invoice->getStation()))return$access->denyStation();if(!$invoice||$amount<=0)return $this->json(['message'=>'Facture et montant obligatoires'],422);$already=0;foreach($em->getRepository(SupplierPayment::class)->findBy(['invoice'=>$invoice,'status'=>'EXECUTED'])as$p)$already+=(float)$p->getAmount();if($amount>(float)$invoice->getTotalAmount()-$already+.01)return $this->json(['message'=>'Le paiement dépasse le solde de la facture'],422);$p=(new SupplierPayment())->setSupplier($invoice->getSupplier())->setInvoice($invoice)->setStation($invoice->getStation())->setPaymentDate(new \DateTimeImmutable($d['date']??'today'))->setAmount((string)$amount)->setPaymentMethod((string)($d['method']??'BANK_TRANSFER'))->setReference(trim((string)($d['reference']??''))?:null)->setNote(trim((string)($d['note']??''))?:null)->setCreatedAt(new \DateTimeImmutable());$em->persist($p);$em->flush();return $this->json(['id'=>$p->getId()],201);}
